'use strict';
(()=>{const B=BABYLON,V=B.Vector3,$=id=>document.getElementById(id),canvas=$('viewer');const engine=new B.Engine(canvas,true);engine.setHardwareScalingLevel(Math.max(1,devicePixelRatio/1.5));const scene=new B.Scene(engine);scene.clearColor=new B.Color4(.115,.145,.135,1);scene.environmentTexture=B.CubeTexture.CreateFromPrefilteredData('assets/characters/environment.env',scene);scene.environmentIntensity=.8;scene.imageProcessingConfiguration.toneMappingEnabled=true;scene.imageProcessingConfiguration.toneMappingType=B.ImageProcessingConfiguration.TONEMAPPING_ACES;scene.imageProcessingConfiguration.exposure=1.15;const camera=new B.ArcRotateCamera('inspection',-Math.PI/2-.18,1.32,5,new V(0,1.25,0),scene);camera.attachControl(canvas,true);camera.lowerRadiusLimit=1.5;camera.upperRadiusLimit=12;camera.lowerBetaLimit=.2;camera.upperBetaLimit=1.65;camera.wheelPrecision=35;camera.panningSensibility=0;camera.minZ=.05;
const fill=new B.HemisphericLight('softbox',new V(0,1,-.5),scene);fill.intensity=.7;fill.diffuse=new B.Color3(.8,.88,1);const key=new B.DirectionalLight('warm key',new V(-.6,-1,.7),scene);key.position.set(4,7,-4);key.intensity=2.3;key.diffuse=new B.Color3(1,.88,.72);const rim=new B.DirectionalLight('rim',new V(.4,-.6,-1),scene);rim.intensity=1.5;rim.diffuse=new B.Color3(.68,.8,1);const shadows=new B.ShadowGenerator(2048,key);shadows.useBlurExponentialShadowMap=true;shadows.blurKernel=32;shadows.darkness=.25;const floor=B.MeshBuilder.CreateCylinder('display plinth',{diameter:7,height:.08,tessellation:64},scene);floor.position.y=-.06;floor.receiveShadows=true;const floorMat=new B.PBRMaterial('charcoal stage',scene);floorMat.albedoColor=new B.Color3(.12,.145,.13);floorMat.metallic=.1;floorMat.roughness=.82;floor.material=floorMat;const system=EdoCharacters.create(scene,shadows);let actor,walking=false;const names={samurai:['侍','ARMORED WARRIOR','漆の甲冑、織り紐、鉄の兜。<br>高精細な立体モデルと表面の質感。'],cavalry:['騎馬兵','MOUNTED WARRIOR','毛並みを持つ馬と、甲冑姿の騎手。<br>接近戦では突進の構えに警戒。'],shogun:['将軍','SHOGUN / MID BOSS','朱漆と金の装飾、背に掲げた指物。<br>宿場を脅かす指揮官。'],bandit:['山賊','ROADSIDE BANDIT','盗み集めた甲冑、使い込まれた革と織り紐。<br>茶褐色の装備をまとい、街道を脅かす。'],oni:['赤鬼','RED ONI / BOSS','筋肉の起伏、曲がった角、牙と鉄の金棒。<br>巨大な体格を持つ異形。']};
function choose(kind){if(actor){system.dispose(actor);actor.root.dispose();}const root=new B.TransformNode('preview actor',scene);if(kind==='shogun')root.scaling.setAll(1.25);if(kind==='oni')root.scaling.setAll(1.85);actor={root,kind,phase:0,action:walking?'approach':'recover',dead:false,rage:false};system.attach(actor);$('viewer-name').textContent=names[kind][0];$('viewer-tag').textContent=names[kind][1];$('viewer-description').innerHTML=names[kind][2];document.querySelectorAll('[data-kind]').forEach(btn=>btn.classList.toggle('selected',btn.dataset.kind===kind));camera.target.set(0,kind==='oni'?2.05:kind==='cavalry'?1.65:1.25,0);camera.radius=kind==='oni'?7.5:kind==='cavalry'?6:4.6;camera.alpha=-Math.PI/2-.18;camera.beta=1.3;}
document.querySelectorAll('[data-kind]').forEach(btn=>btn.onclick=()=>choose(btn.dataset.kind));$('motion').onclick=()=>{walking=!walking;$('motion').textContent=walking?'静止する':'歩行を見る';actor.action=walking?'approach':'recover';};system.loading.then(()=>{choose('samurai');$('viewer-loading').style.display='none';}).catch(()=>{$('viewer-loading').textContent='読み込みに失敗しました。ページを再読み込みしてください。';});engine.runRenderLoop(()=>{if(actor){actor.phase+=Math.min(.05,engine.getDeltaTime()/1000)*7;system.tick(actor,!walking);}scene.render();});window.addEventListener('resize',()=>engine.resize());})();
